/// Raven `SanitizeString`.
///
/// Remove case and control characters.
///
/// Source: `oracle/oracle/codemp/game/g_cmds.c:161-175`
pub fn SanitizeString(
    r#in: *mut c_char,
    out: *mut c_char,
) {
    unsafe {
        let mut i = r#in;
        let mut o = out;
        loop {
            let c = *i as u8;
            if c == 0 {
                break;
            }
            if c == 27 {
                // skip color code
                i = i.add(2);
                continue;
            }
            if (c as i8) < 32 {
                i = i.add(1);
                continue;
            }
            *o = (c as char).to_ascii_lowercase() as c_char;
            o = o.add(1);
            i = i.add(1);
        }
        *o = 0;
    }
}

