/// Raven `G_ClientNumberFromName`.
///
/// Finds the client number of the client with the given name.
///
/// Source: `oracle/oracle/codemp/game/g_cmds.c:1871-1890`
pub fn G_ClientNumberFromName(
    ctx: GameContext<'_>,
    name: *const c_char,
) -> c_int {
    unsafe {
        let mut s2 = [0 as c_char; MAX_STRING_CHARS];
        let mut n2 = [0 as c_char; MAX_STRING_CHARS];

        // check for a name match
        SanitizeString(name as *mut c_char, s2.as_mut_ptr());
        let clients = (*ctx.world).level.clients;
        for i in 0..(*ctx.world).level.numConnectedClients {
            let cl = clients.add(i as usize);
            SanitizeString((*cl).pers.netname.as_ptr() as *mut c_char, n2.as_mut_ptr());
            if cstr_eq(n2.as_ptr(), s2.as_ptr()) {
                return i;
            }
        }

        -1
    }
}

/// Raven `SanitizeString2`.
///
/// Rich's revised version of `SanitizeString`.
///
/// Source: `oracle/oracle/codemp/game/g_cmds.c:1899-1937`
pub fn SanitizeString2(
    r#in: *mut c_char,
    out: *mut c_char,
) {
    const MAX_NAME_LENGTH: usize = 32; // Source: `oracle/oracle/codemp/game/bg_public.h`
    unsafe {
        let mut i: isize = 0;
        let mut r: isize = 0;

        loop {
            let c = *r#in.offset(i) as u8;
            if c == 0 {
                break;
            }
            if i as usize >= MAX_NAME_LENGTH - 1 {
                // the ui truncates the name here..
                break;
            }

            if c == b'^' {
                let next = *r#in.offset(i + 1) as u8;
                if next >= b'0' && next <= b'9' {
                    // only skip it if there's a number after it for the color
                    i += 2;
                    continue;
                } else {
                    // just skip the ^
                    i += 1;
                    continue;
                }
            }

            if (c as i8) < 32 {
                i += 1;
                continue;
            }

            *out.offset(r) = c as c_char;
            r += 1;
            i += 1;
        }

        *out.offset(r) = 0;
    }
}

