pub fn G_OtherPlayersDueling(ctx: GameContext<'_>) -> qboolean {
    unsafe {
        for i in 0..MAX_CLIENTS {
            let ent = &mut (*ctx.world).entities[i] as *mut gentity_t;
            let client = (*ent).client as *mut gclient_t;

            if (*ent).inuse != qfalse
                && !client.is_null()
                && (*client).ps.duelInProgress != qfalse
            {
                return qtrue;
            }
        }

        qfalse
    }
}

